import { View, Text, TextInput, KeyboardAvoidingView, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    // энд бичнэ үү: SafeAreaView-ээр ороо
    <View style={styles.safe}>
      <Text style={styles.h}>Хүргэлтийн хаяг</Text>
      <KeyboardAvoidingView style={styles.body}>
        <TextInput nativeID="addr" style={styles.input} placeholder="Гэрийн хаяг" />
      </KeyboardAvoidingView>
    </View>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: "#fff" },
  h: { fontSize: 20, fontWeight: "bold", padding: 20 },
  body: { flex: 1, padding: 20 },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14, fontSize: 16 },
});

registerRootComponent(App);

